window.AUTH=window.AUTH||{};window.AUTH["22-859"]={"d":"22-859","id":"2023/22-859","n":"Securities and Exchange Commission v. Jarkesy","briefs":[{"k":"petitioner","label":"Brief of petitioner Securites and Exchange Commission","date":"2023-08-28","url":"https://www.supremecourt.gov/DocketPDF/22/22-859/278330/20230828183013049_22-859tsUnitedStates.pdf","side":"pet","n":160},{"k":"respondent","label":"Brief of respondents George R. Jarkesy, Jr., et al.","date":"2023-10-11","url":"https://www.supremecourt.gov/DocketPDF/22/22-859/284699/20231011140507326_22-859%20Respondents%20Brief.pdf","side":"res","n":82},{"k":"reply","label":"Reply of petitioner Securites and Exchange Commission","date":"2023-11-13","url":"https://www.supremecourt.gov/DocketPDF/22/22-859/289467/20231113164043876_22-859%20SEC%20v.%20Jarkesy.pdf","side":"pet","n":52}],"opinion":"https://www.supremecourt.gov/opinions/23pdf/603us1r50_7kh7.pdf","tr":true,"items":[{"t":"case","label":"A. L. A. Schechter Poultry Corp. v. United States","cite":"295 U.S. 495","y":1935,"id":"1900-1940/295us495","sc":1,"by":{"0":"37"}},{"t":"case","label":"Abrams v. SSA","cite":"703 F.3d 538","y":2012,"court":"Fed. Cir.","url":"https://www.courtlistener.com/c/F.3d/703/538/","by":{"0":"60","2":"24"},"q":[{"src":"brief","b":0,"text":"good cause standard must be construed as including all matters which affect the ability and fitness of the ALJ to perform the duties of office.","cite":"703 F.3d 538, 543"},{"src":"brief","b":2,"text":"good cause standard must be construed as including all matters which affect the ability and fitness of the ALJ to perform the duties of the office.","cite":"703 F.3d 538, 543"}]},{"t":"case","label":"Andrews v. King","cite":"77 Me. 224","y":1885,"url":"https://www.courtlistener.com/c/Me./77/224/","by":{"0":"64"}},{"t":"case","label":"Atlas Roofing Co. v. Occupational Safety & Health Review Comm’n","cite":"430 U.S. 442","y":1977,"id":"1976/75-746","sc":1,"by":{"0":"13, 18, 19, 21-25, 28, 31, 44","1":"27, 32-34, 37-38, 45-46","2":"3, 6-10"},"q":[{"src":"brief","b":0,"text":"to an administrative agency the function of deciding whether a violation has in fact occurred.","cite":"430 U.S. 442, 450"},{"src":"brief","b":0,"text":"where the Government is involved in its sovereign capacity under an otherwise valid statute creating enforceable public rights.","cite":"430 U.S. 442, 458"},{"src":"brief","b":2,"text":"to an administrative agency the function of deciding whether a violation has in fact occurred.","cite":"430 U.S. at 450"},{"src":"brief","b":2,"text":"state common-law actions for negligence and wrongful death.","cite":"430 U.S. at 445"},{"src":"opinion","who":"Opinion of the Court (Chief Justice Roberts)","text":"`not . . . suit[s] at common law or in the nature of such . . . suit[s].'","cite":"430 U. S., at 453"},{"src":"opinion","who":"Opinion of the Court (Chief Justice Roberts)","text":"`[W]here the action involves rights and remedies recognized at common law, it must preserve to parties their right to a jury trial.'","cite":"430 U. S., at 458"},{"src":"argument","who":"Mr. Fletcher","text":"First, this Court's decision in Atlas Roofing considered many of the same arguments presented today and reaffirmed that Congress does not violate the Seventh Amendment when it authorizes an agency to impose civil penalties in administrative proceedings to enforce a federal statute."},{"src":"argument","who":"Mr. Fletcher","text":"We take this Court's statement of the public rights doctrine from Atlas Roofing and other cases, and the argument we're making here is limited to the particular strand of the public rights doctrine that the Court has described in Atlas and other cases."},{"src":"argument","who":"Mr. Fletcher","text":"I think what I'd say is the strand of the doctrine that's relevant here is the same one from Atlas, which is, when the federal government, an agency, is enforcing a federal statute in exercise of its sovereign powers, that's a matter involving public rights."}]},{"t":"case","label":"Baldwin v. New York","cite":"399 U.S. 66","y":1970,"id":"1969/188","sc":1,"by":{"0":"44"}},{"t":"case","label":"Biggs v. McBride","cite":"21 P. 878","y":1889,"court":"Or.","url":"https://www.courtlistener.com/c/P./21/878/","by":{"0":"64"}},{"t":"case","label":"Block v. Hirsh","cite":"256 U.S. 135","y":1921,"id":"scdb/1920-112","sc":1,"by":{"0":"20, 28"}},{"t":"case","label":"Buckley v. Valeo","cite":"424 U.S. 1","y":1976,"id":"1975/75-436","sc":1,"by":{"0":"35"}},{"t":"case","label":"Butz v. Economou","cite":"438 U.S. 478","y":1978,"id":"1977/76-709","sc":1,"by":{"0":"53, 54, 66","1":"67","2":"27"},"q":[{"src":"brief","b":0,"text":"free from pressures by the parties or other officials within the agency.","cite":"438 U.S. at 513"},{"src":"brief","b":1,"text":"free from pressures by the parties or other officials within the agency.","cite":"438 U.S. 478, 513-514"},{"src":"brief","b":2,"text":"free from pressures by the parties or other officials within the agency,","cite":"438 U.S. 478, 513-514"}]},{"t":"case","label":"City of Arlington v. FCC","cite":"569 U.S. 290","y":2013,"id":"2012/11-1545","sc":1,"by":{"0":"37","1":"57, 59","2":"4"},"q":[{"src":"brief","b":1,"text":"fill statutory and regulatory interstices comprehendsively with [their] own policy judgments.","cite":"569 U.S. at 304"},{"src":"brief","b":2,"text":"conduct adjudications * * * and have done so since the beginning of the Republic.","cite":"569 U.S. 290, 304 n.4"},{"src":"argument","who":"Mr. Fletcher","text":"Murray's Lessee, City of Arlington, this Court has long recognized that it's executive power to apply the law to the facts and impose consequences prescribed by law in particular cases."},{"src":"argument","who":"Mr. Fletcher","text":"And the lesson from all of this Court's cases -- City of Arlington, Murray's Lessee -- is that even when the executive branch conducts an adjudication and applies the law to the facts, even if it looks like trial-type procedures to enhance fairness, that's not the sort of suit that requires an exercise of the judicial power or comes with --"}]},{"t":"case","label":"Collins v. Yellen","cite":"141 S. Ct. 1761","y":2021,"id":"2020/19-422","sc":1,"by":{"0":"67","1":"53, 55, 65-66, 72","2":"24, 26, 29, 30"},"q":[{"src":"brief","b":1,"text":"does not mean the same thing as ‘at will.’","cite":"141 S. Ct. 1761, 1787"},{"src":"brief","b":1,"text":"[W]hen Congress includes particular language in one section of a statute but omits it in another section of the same Act,","cite":"141 S.Ct. at 1782"},{"src":"brief","b":2,"text":"had attempted to remove [an ALJ] but was prevented from doing so.","cite":"141 S. Ct. at 1789"}]},{"t":"case","label":"Commodity Futures Trading Comm’n v. Schor","cite":"478 U.S. 833","y":1986,"id":"1985/85-621","sc":1,"by":{"0":"28","1":"39-40, 44","2":"7"},"q":[{"src":"opinion","who":"Justice Gorsuch, concurring","text":"the concerns that drove Congress to depart from the requirements of Article III.","cite":"478 U. S., at 851"},{"src":"opinion","who":"Justice Sotomayor, dissenting","text":"`limit[ing] the judicial authority of non-Article III federal tribunals'","cite":"478 U. S. 833, 859"}]},{"t":"case","label":"Commonwealth v. Slifer","cite":"25 Pa. 23","y":1855,"url":"https://www.courtlistener.com/c/Pa./25/23/","by":{"0":"64"}},{"t":"case","label":"Crowell v. Benson","cite":"285 U.S. 22","y":1932,"id":"scdb/1931-083","sc":1,"by":{"0":"18, 28","1":"40, 50","2":"16"},"q":[{"src":"brief","b":0,"text":"covers matters ‘which arise between the Government and persons subject to its authority in connection with the performance of the constitutional functions of the executive or legislative departments.’","cite":"285 U.S. 22, 50"},{"src":"opinion","who":"Justice Sotomayor, dissenting","text":"between the government and persons subject to its authority in connection with the performance of the constitutional functions of the executive or legislative departments.","cite":"285 U. S., at 50"},{"src":"opinion","who":"Justice Sotomayor, dissenting","text":"interstate and foreign commerce, taxation, immigration, the public lands, public health, the facilities of the post offce, pensions and payments to veterans,","cite":"285 U. S., at 51"},{"src":"argument","who":"Mr. Fletcher","text":"Not if we're talking about adjudicating matters of private rights. In Crowell's terms, the liability of one person --"}]},{"t":"case","label":"Department of Commerce v. New York","cite":"139 S. Ct. 2551","y":2019,"id":"2018/18-966","sc":1,"by":{"0":"51"}},{"t":"case","label":"Dullam v. Willson","cite":"19 N.W. 112","y":1884,"court":"Mich.","url":"https://www.courtlistener.com/c/N.W./19/112/","by":{"0":"64"}},{"t":"case","label":"Edmond v. United States","cite":"520 U.S. 651","y":1997,"id":"1996/96-262","sc":1,"by":{"0":"56"},"q":[{"src":"brief","b":0,"text":"attempt to influence * * * the outcome of individual proceedings.","cite":"520 U.S. 651, 664"}]},{"t":"case","label":"Ernst & Ernst v. Hochfelder","cite":"425 U.S. 185","y":1976,"id":"1975/74-1042","sc":1,"by":{"0":"3, 31"},"q":[{"src":"brief","b":0,"text":"protect investors against manipulation of stock prices through regulation of transactions upon securities exchanges and in over-the-counter markets.","cite":"425 U.S. at 195"},{"src":"opinion","who":"Justice Sotomayor, dissenting","text":"protect investors against manipulation of stock prices,","cite":"425 U. S. 185, 195"}]},{"t":"case","label":"Flaherty & Crumrine Preferred Income Fund, Inc. v. TXU Corp.","cite":"565 F.3d 200","y":2009,"url":"https://www.courtlistener.com/c/F.3d/565/200/","by":{"0":"30"}},{"t":"case","label":"Free Enter. Fund v. PCAOB","cite":"561 U.S. 477","y":2010,"id":"2009/08-861","sc":1,"by":{"0":"54","1":"45, 52-55, 57,59, 62, 68"},"q":[{"src":"brief","b":0,"text":"may slip from the Executive’s control, and thus from that of the people.","cite":"561 U.S. at 499"},{"src":"brief","b":0,"text":"deprive[s] the President of adequate control","cite":"561 U.S. at 508"},{"src":"brief","b":1,"text":"the Constitution gives the President ‘the authority to remove those who assist him in carrying out his duties,’","cite":"561 U.S. at 513"},{"src":"brief","b":1,"text":"Since 1789, the Constitution has been understood to empower the President to keep...officers accountable—by removing them from office, if necessary.","cite":"561 U.S. at 483"},{"src":"opinion","who":"Justice Sotomayor, dissenting","text":"political power . . . operates.","cite":"561 U. S., at 523"}]},{"t":"case","label":"Granfinanciera, S. A. v. Nordberg","cite":"492 U.S. 33","y":1989,"id":"1988/87-1716","sc":1,"by":{"0":"9, 20, 26-28","1":"26, 29, 40-43, 45","2":"7, 8"},"q":[{"src":"brief","b":0,"text":"whether jury trials would ‘go far to dismantle the statutory scheme.’","cite":"492 U.S. at 60"},{"src":"brief","b":0,"text":"action must be tried under the auspices of an Article III court, * * * the Seventh Amendment affords the parties a right to a jury trial whenever the cause of action is legal in nature.","cite":"492 U.S. 33, 53"},{"src":"brief","b":2,"text":"where the Government is involved in its sovereign capacity.","cite":"492 U.S. 33, 51"},{"src":"brief","b":2,"text":"cases not involving the Federal Government","cite":"492 U.S. at 54"},{"src":"opinion","who":"Justice Sotomayor, dissenting","text":"disputes to which the Federal Government is not a party in its sovereign capacity.","cite":"492 U. S. 33, 55, n. 10"},{"src":"argument","who":"Mr. Fletcher","text":"But I think the difference between those cases and this one is that in this case, we're talking about what we had in Atlas, which is a federal agency that's charged with enforcing rights enacted for the benefit of the public, in Justice Scalia's words in Granfinanciera, rights held by the public, and that --"},{"src":"argument","who":"Justice Gorsuch","text":"I want to talk to you for just a minute about how you deal with Tull and Granfinanciera. We agree that Tull found that some civil penalties under the Clean Water Act imposed by the government do trigger the Seventh Amendment, right?"},{"src":"argument","who":"Justice Gorsuch","text":"Okay. So let's talk about Granfinanciera, which applied Tull's test in a non-Article III tribunal, right?"}]},{"t":"case","label":"Gundy v. United States","cite":"139 S. Ct. 2116","y":2019,"id":"2018/17-6086","sc":1,"by":{"0":"15, 36, 37","1":"49"},"q":[{"src":"brief","b":0,"text":"powers which are strictly and exclusively legislative.","cite":"139 S. Ct. 2116, 2123"},{"src":"brief","b":1,"text":"powers which are strictly and exclusively legislative.","cite":"139 S. Ct. 2116, 2123"}]},{"t":"case","label":"Ham v. Board of Police","cite":"7 N.E. 540","y":1886,"court":"Mass.","url":"https://www.courtlistener.com/c/N.E./7/540/","by":{"0":"64"}},{"t":"case","label":"Heckler v. Chaney","cite":"470 U.S. 821","y":1985,"id":"1984/83-1878","sc":1,"by":{"0":"15, 34-36","2":"15"},"q":[{"src":"brief","b":0,"text":"This Court has recognized on several occasions over many years that an agency’s decision not to prose- cute or enforce, whether through civil or criminal process, is a decision generally committed to an agency’s absolute discretion.","cite":"470 U.S. 821, 831"},{"src":"brief","b":2,"text":"no meaningful standard against which to judge the agency’s exercise of discretion","cite":"470 U.S. 821, 830"}]},{"t":"case","label":"Helvering v. Mitchell","cite":"303 U.S. 391","y":1938,"id":"scdb/1937-140","sc":1,"by":{"0":"22"},"q":[{"src":"argument","who":"Mr. Fletcher","text":"You know, Atlas itself is relying on a line of decisions that go back to Helvering versus Mitchell, to the two Elting cases, to Stranahan from 1909, and -- and even before that, all of which stand for the same proposition that civil penalties in government enforcement actions are permissible, consistent with Article III and the Seventh Amendment."},{"src":"argument","who":"Mr. Fletcher","text":"That same thing is reflected in Passavant, which is a case from the -- 1893, in the Elting cases from 1932, in Helvering versus Mitchell, and those aren't just, you know, pinpoints in the landscape."}]},{"t":"case","label":"HHS v. Jarboe","cite":"2023 M.S.P.B. 22","y":2023,"court":"Aug. 2","url":"https://www.courtlistener.com/c/M.S.P.B./2023/22/","by":{"0":"60, 63","2":"21"}},{"t":"case","label":"Hughes v. SEC","cite":"174 F.2d 969","y":1949,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/174/969/","by":{"0":"30"}},{"t":"case","label":"Humphrey’s Ex’r v. United States","cite":"295 U.S. 602","y":1935,"id":"1900-1940/295us602","sc":1,"by":{"0":"62","1":"55-56, 58"}},{"t":"case","label":"INS v. Chadha","cite":"462 U.S. 919","y":1983,"id":"1981/80-1832","sc":1,"by":{"0":"9, 40-43","1":"61"},"q":[{"src":"brief","b":0,"text":"[g]overnment actions are ‘legislative’ if they have ‘the purpose and effect of altering the legal rights, duties and relations of persons . . . outside the legislative branch.’","cite":"462 U.S. 919, 952"},{"src":"brief","b":1,"text":"[T]he fact that a given law or procedure is efficient, convenient, and useful in facilitating functions of government, standing alone, will not save it if it is contrary to the Constitution.","cite":"462 U.S. 919, 944"}]},{"t":"case","label":"Kokesh v. SEC","cite":"581 U.S. 455","y":2017,"id":"2016/16-529","sc":1,"by":{"0":"24","2":"9"},"q":[{"src":"brief","b":0,"text":"it acts in the public interest, to remedy harm to the public at large.","cite":"581 U.S. 455, 463"},{"src":"brief","b":2,"text":"‘remedy harm to the public at large.’","cite":"581 U.S. 455, 463"},{"src":"opinion","who":"Justice Sotomayor, dissenting","text":"is why, for example, a securities-enforcement action may proceed even if victims do not support or are not parties to the prosecution.","cite":"581 U. S. 455, 463"},{"src":"argument","who":"Mr. Fletcher","text":"And so we don't require a showing of reliance. We don't require a showing of damage to private parties. As this Court said in Kokesh, what we're looking for --"},{"src":"argument","who":"Mr. Fletcher","text":"I think the clearest indication of that is this Court's decision in Kokesh, which explained why the remedies that the SEC gets, even when they are monetary or compensatory, are not for private parties."}]},{"t":"case","label":"Lloyd Sabaudo Societa Anonima Per Azioni v. Elting","cite":"287 U.S. 329","y":1932,"id":"scdb/1932-015","sc":1,"by":{"0":"23"}},{"t":"case","label":"Loving v. United States","cite":"517 U.S. 748","y":1996,"id":"1995/94-1966","sc":1,"by":{"0":"38"}},{"t":"case","label":"Lucia v. SEC","cite":"138 S. Ct. 2044","y":2018,"id":"2017/17-130","sc":1,"by":{"0":"7, 49, 58","1":"52, 57, 65, 71-72","2":"22, 29"},"q":[{"src":"brief","b":1,"text":"contravene the Constitution's separation of powers.","cite":"138 S.Ct. at 2053"}]},{"t":"case","label":"Lynch v. Chase","cite":"40 P. 666","y":1895,"court":"Kan.","url":"https://www.courtlistener.com/c/P./40/666/","by":{"0":"64"}},{"t":"case","label":"Marshall Field v. Clark","cite":"143 U.S. 649","y":1892,"id":"scdb/1891-139","sc":1,"by":{"0":"37","1":"48-49","2":"17"}},{"t":"case","label":"Mistretta v. United States","cite":"488 U.S. 361","y":1989,"id":"1988/87-7028","sc":1,"by":{"0":"36, 37","1":"49","2":"17"},"q":[{"src":"brief","b":0,"text":"clearly delineates the general policy, the public agency which is to apply it, and the boundaries of this delegated authority.","cite":"488 U.S. 361, 372-373"}]},{"t":"case","label":"Morrison v. Olson","cite":"487 U.S. 654","y":1988,"id":"1987/87-1279","sc":1,"by":{"0":"47, 50, 60-62","1":"56, 58","2":"18, 19, 21"},"q":[{"src":"brief","b":0,"text":"impermissibly burdens the President’s power to control or supervise","cite":"487 U.S. at 692"},{"src":"brief","b":0,"text":"the functions of the officials in question.","cite":"487 U.S. at 691"}]},{"t":"case","label":"Myers v. United States","cite":"272 U.S. 52","y":1926,"id":"1900-1940/272us52","sc":1,"by":{"0":"46, 47, 50, 55","1":"55, 60-61","2":"18, 19, 24, 26"},"q":[{"src":"brief","b":0,"text":"removals in the case of inferior executive officers","cite":"272 U.S. 52, 127"},{"src":"brief","b":2,"text":"prescribe incidental regulations controlling and restricting the latter in the exercise of the power of removal,","cite":"272 U.S. at 161"}]},{"t":"case","label":"N. Sims Organ & Co. v. SEC","cite":"293 F.2d 78","y":1961,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.2d/293/78/","by":{"0":"30"}},{"t":"case","label":"NLRB v. Jones & Laughlin Steel Corp.","cite":"301 U.S. 1","y":1937,"id":"1900-1940/301us1","sc":1,"by":{"0":"19"},"q":[{"src":"brief","b":0,"text":"is not a suit at common law or in the nature of such a suit.","cite":"301 U.S. 1, 48"}]},{"t":"case","label":"NLRB v. Noel Canning","cite":"573 U.S. 513","y":2014,"id":"2013/12-1281","sc":1,"by":{"0":"65","2":"13"},"q":[{"src":"brief","b":0,"text":"threequarters of a century of settled practice is long enough to entitle [the] practice to ‘great weight’","cite":"573 U.S. 513, 533"}]},{"t":"case","label":"North Am. Co. v. SEC","cite":"327 U.S. 686","y":1946,"id":"scdb/1945-064","sc":1,"by":{"0":"24"}},{"t":"case","label":"Oceanic Steam Navigation Co. v. Stranahan","cite":"214 U.S. 320","y":1909,"id":"scdb/1908-176","sc":1,"by":{"0":"23","1":"50","2":"7, 13, 16"},"q":[{"src":"brief","b":0,"text":"delegate to administrative officers final and conclusive authority as to the valuation of imported merchandise, accompanied with the power to impose a penalty for undervaluation.","cite":"214 U.S. at 339"},{"src":"brief","b":2,"text":"it was within the competency of Congress, when legislating as to matters exclusively within its control, to impose appropriate obligations and sanction their enforcement by reasonable monetary penalties, giving to executive officers the power to enforce such penalties without the necessity of invoking the judicial power.","cite":"214 U.S. at 339"},{"src":"opinion","who":"Justice Gorsuch, concurring","text":"`without the necessity of invoking the judicial power.'","cite":"214 U. S., at 339"},{"src":"opinion","who":"Justice Sotomayor, dissenting","text":"without the necessity of invoking the judicial power.","cite":"214 U. S., at 339"},{"src":"argument","who":"Mr. Fletcher","text":"I think the best one to look at if you were just going to pick one is Oceanic Steam Navigation versus Stranahan. It's an immigration case from 1909."}]},{"t":"case","label":"Oil States Energy Servs., LLC v. Greene’s Energy Grp., LLC","cite":"138 S. Ct. 1365","y":2018,"id":"2017/16-712","sc":1,"by":{"0":"13, 18, 20, 21, 32, 33","1":"28, 43-44, 46","2":"4, 5, 11"},"q":[{"src":"brief","b":0,"text":"properly assigns a matter to adjudication in a non-Article III tribunal, ‘the Seventh Amendment poses no independent bar to the adjudication of that action by a nonjury factfinder.’","cite":"138 S. Ct. 1365, 1379"},{"src":"brief","b":0,"text":"Consequently, Congress cannot confer the Government’s judicial Power on entities outside Article III.","cite":"138 S. Ct. 1365, 1372-1373"},{"src":"brief","b":2,"text":"confer[red] the Government’s ‘judicial Power’ on entities outside Article III.","cite":"138 S. Ct. 1365, 1372-1373"},{"src":"brief","b":2,"text":"significant latitude to assign adjudication of public rights to entities other than Article III courts.","cite":"138 S. Ct. at 1373"}]},{"t":"case","label":"Panama Ref. Co. v. Ryan","cite":"293 U.S. 388","y":1935,"id":"1900-1940/293us388","sc":1,"by":{"0":"36, 37"}},{"t":"case","label":"Passavant v. United States","cite":"148 U.S. 214","y":1893,"id":"scdb/1892-141","sc":1,"by":{"0":"23"},"q":[{"src":"argument","who":"Mr. Fletcher","text":"That same thing is reflected in Passavant, which is a case from the -- 1893, in the Elting cases from 1932, in Helvering versus Mitchell, and those aren't just, you know, pinpoints in the landscape."}]},{"t":"case","label":"People ex rel. Mayor v. Nichols","cite":"79 N.Y. 582","y":1880,"url":"https://www.courtlistener.com/c/N.Y./79/582/","by":{"0":"64"}},{"t":"case","label":"Perry v. Sindermann","cite":"408 U.S. 593","y":1972,"id":"1971/70-36","sc":1,"by":{"0":"63"}},{"t":"case","label":"Ramspeck v. Federal Trial Exam’rs Conference","cite":"345 U.S. 128","y":1953,"id":"scdb/1952-062","sc":1,"by":{"0":"53, 60, 66","1":"68","2":"26, 27"},"q":[{"src":"brief","b":0,"text":"reduction in force * * * is good cause.","cite":"345 U.S. at 143"},{"src":"brief","b":0,"text":"[m]any complaints were voiced against the actions of the hearing examiners, it being charged that they were mere tools of the agency concerned and subservient to the agency heads in making their proposed findings of fact and recommendations.","cite":"345 U.S. at 131"},{"src":"brief","b":1,"text":"Congress intended to make hearing examiners a special class of semi-independent subordinate hearing officers by vesting control of their compensation, promotion and tenure in the Civil Service Commission.","cite":"345 U.S. 128, 132"},{"src":"brief","b":2,"text":"were mere tools of the agency concerned and subservient to the agency heads in making their proposed findings of fact and recommendations.","cite":"345 U.S. 128, 131"}]},{"t":"case","label":"Reagan v. United States","cite":"182 U.S. 419","y":1901,"id":"scdb/1900-066","sc":1,"by":{"0":"63"},"q":[{"src":"brief","b":0,"text":"where causes of removal are specified by constitution or statute.","cite":"182 U.S. 419, 425"}]},{"t":"case","label":"SEC v. Blavin","cite":"760 F.2d 706","y":1985,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.2d/760/706/","by":{"0":"25, 30"},"q":[{"src":"brief","b":0,"text":"the Commission is not required to prove that any investor actually relied on [a party’s] misrepresentations or that the misrepresentations caused any investor to lose money.","cite":"760 F.2d at 711"}]},{"t":"case","label":"SEC v. Capital Gains Research Bureau, Inc.","cite":"375 U.S. 180","y":1963,"id":"1963/42","sc":1,"by":{"0":"3, 31","1":"36-37"},"q":[{"src":"brief","b":0,"text":"achieve a high standard of business ethics in the securities industry.","cite":"375 U.S. 180, 186"},{"src":"brief","b":0,"text":"‘not only * * * dishonor, but also * * * conduct that tempts dishonor.’","cite":"375 U.S. at 199"}]},{"t":"case","label":"SEC v. Chenery Corp.","cite":"332 U.S. 194","y":1947,"id":"scdb/1946-133","sc":1,"by":{"0":"52"}},{"t":"case","label":"Seila Law LLC v. CFPB","cite":"140 S. Ct. 2183","y":2020,"id":"2019/19-7","sc":1,"by":{"0":"47, 50, 51","1":"52, 54-59","2":"19, 26, 28"},"q":[{"src":"brief","b":0,"text":"remain dependent on the President, who in turn is accountable to the people,","cite":"140 S. Ct. at 2211"},{"src":"brief","b":1,"text":"The entire ‘executive Power’ belongs to the President alone.","cite":"140 S. Ct. 2183, 2197"},{"src":"brief","b":1,"text":"the most direct method of presidential control,","cite":"140 S. Ct. at 2204"},{"src":"brief","b":2,"text":"one for multimember expert agencies that do not wield substantial executive power, and one for inferior officers with limited duties and no policymaking or administrative authority.","cite":"140 S. Ct. 2183, 2199-2200"},{"src":"argument","who":"Mr. Fletcher","text":"That's the through line of this Court's recent cases like Seila Law, like Arthrex, like Collins. No foothold in history or tradition is a telling constitutional problem."}]},{"t":"case","label":"Shurtleff v. United States","cite":"189 U.S. 311","y":1903,"id":"scdb/1902-126","sc":1,"by":{"0":"63, 64"},"q":[{"src":"brief","b":0,"text":"a removal is made without such notice, there is a conclusive presumption that the officer was not removed for any of those causes.","cite":"189 U.S. 311, 317"},{"src":"brief","b":0,"text":"held that where an officer may be removed for certain causes, he is entitled to notice and a hearing.","cite":"189 U.S. at 314"}]},{"t":"case","label":"SSA v. Burris","cite":"39 M.S.P.R. 51","y":1988,"url":"https://www.courtlistener.com/c/M.S.P.R./39/51/","by":{"0":"60"}},{"t":"case","label":"SSA v. Goodman","cite":"19 M.S.P.R. 321","y":1984,"url":"https://www.courtlistener.com/c/M.S.P.R./19/321/","by":{"0":"60","1":"63"}},{"t":"case","label":"SSA v. Levinson","cite":"2023 M.S.P.B. 20","y":2023,"court":"July 12","url":"https://www.courtlistener.com/c/M.S.P.B./2023/20/","by":{"0":"63","2":"22"}},{"t":"case","label":"SSA v. Long","cite":"113 M.S.P.R. 190","y":2010,"url":"https://www.courtlistener.com/c/M.S.P.R./113/190/","by":{"0":"60"}},{"t":"case","label":"SSA v. Mills","cite":"73 M.S.P.R. 463","y":1996,"url":"https://www.courtlistener.com/c/M.S.P.R./73/463/","by":{"0":"60"}},{"t":"case","label":"SSA v. Steverson","cite":"111 M.S.P.R. 649","y":2009,"url":"https://www.courtlistener.com/c/M.S.P.R./111/649/","by":{"0":"60"}},{"t":"case","label":"State ex rel. Attorney Gen. v. Hawkins","cite":"5 N.E. 228","y":1886,"court":"Ohio","url":"https://www.courtlistener.com/c/N.E./5/228/","by":{"0":"64"}},{"t":"case","label":"State ex rel. Hart v. Common Council","cite":"55 N.W. 118","y":1893,"court":"Minn.","url":"https://www.courtlistener.com/c/N.W./55/118/","by":{"0":"64"}},{"t":"case","label":"Stern v. Marshall","cite":"564 U.S. 462","y":2011,"id":"2010/10-179","sc":1,"by":{"0":"18","1":"28, 32, 43, 65"},"q":[{"src":"opinion","who":"Opinion of the Court (Chief Justice Roberts)","text":"Article III could neither serve its purpose in the system of checks and balances nor preserve the integrity of judicial decisionmaking Page Proof Pending Publication if the other branches of the Federal Government could confer the Government's `judicial Power' on entities outside Article III.","cite":"564 U. S., at 484"},{"src":"opinion","who":"Justice Gorsuch, concurring","text":"the responsibility for deciding [it] rests with Article III judges in Article III courts,","cite":"564 U. S. 462, 484"},{"src":"argument","who":"Chief Justice Roberts","text":"And it's also what we said in -- in Stern, that the one thing you -- you can't take away from the court, you know, suits made of the stuff of the traditional actions at common law tried by the courts at -- at West -- at Westminster."},{"src":"argument","who":"Mr. Fletcher","text":"That's Granfinanciera, Thomas, Schor, Stern versus Marshall. All of them are careful to carve out and say we're talking about this special zone of liability between two private parties --"},{"src":"argument","who":"Justice Kavanaugh","text":"And in Stern, the Chief Justice's opinion said that public rights extended, quoting Northern Pipeline's plurality, only to matters arising between individuals and the government in connection with the performance of the constitutional functions of the executive or legislative departments that historically could have been determined exclusively by those branches, which suggests a line that may track the Due Process Clause between benefits and penalties."}]},{"t":"case","label":"Stoneridge Inv. Partners, LLC v. Scientific-Atlanta, Inc.","cite":"552 U.S. 148","y":2008,"id":"2007/06-43","sc":1,"by":{"0":"30"},"q":[{"src":"brief","b":0,"text":"Section 10(b) does not incorporate common-law fraud into federal law.","cite":"552 U.S. 148, 162"}]},{"t":"case","label":"Touby v. United States","cite":"500 U.S. 160","y":1991,"id":"1990/90-6282","sc":1,"by":{"0":"37"}},{"t":"case","label":"TransUnion LLC v. Ramirez","cite":"141 S. Ct. 2190","y":2021,"id":"2020/20-297","sc":1,"by":{"0":"35"},"q":[{"src":"brief","b":0,"text":"[T]he choice of how to prioritize and how aggressively to pursue legal actions against defendants who violate the law falls within the discretion of the Executive Branch.","cite":"141 S. Ct. 2190, 2207"}]},{"t":"case","label":"Tull v. United States","cite":"481 U.S. 412","y":1987,"id":"1986/85-1259","sc":1,"by":{"0":"9, 19, 28, 29","1":"12, 30","2":"4, 5, 12"},"q":[{"src":"brief","b":0,"text":"determine whether an action’s claims arise ‘at common law’ under the Seventh Amendment.","cite":"481 U.S. 412, 417"},{"src":"brief","b":0,"text":"is not applicable to administrative proceedings.","cite":"481 U.S. 412, 418 n.4"},{"src":"brief","b":1,"text":"[a] civil penalty was a type of remedy at common law that could only be enforced in courts of law.","cite":"481 U.S. at 418"},{"src":"brief","b":2,"text":"is not applicable to administrative proceedings.","cite":"481 U.S. 412, 418 n.4"},{"src":"brief","b":2,"text":"is more similar to cases that were tried in courts of law than to suits tried in courts of equity or admiralty.","cite":"481 U.S. at 417"},{"src":"opinion","who":"Opinion of the Court (Chief Justice Roberts)","text":"could only be enforced in courts of law.","cite":"481 U. S., at 422"},{"src":"opinion","who":"Justice Sotomayor, dissenting","text":"the Seventh Amendment is not applicable to administrative proceedings.","cite":"481 U. S. 412, 418, n. 4"},{"src":"argument","who":"Justice Gorsuch","text":"I want to talk to you for just a minute about how you deal with Tull and Granfinanciera. We agree that Tull found that some civil penalties under the Clean Water Act imposed by the government do trigger the Seventh Amendment, right?"},{"src":"argument","who":"Justice Gorsuch","text":"What if the government tomorrow decided, well, we don't like those jury trial that come with that, we're -- we're going to -- we're going to effectively overrule Tull by moving those to administrative proceedings?"},{"src":"argument","who":"Justice Gorsuch","text":"-- the key part of that answer is yes, that that would overrule the preexisting Seventh Amendment right this Court recognized in Tull."}]},{"t":"case","label":"United States v. Arthrex, Inc.","cite":"141 S. Ct. 1970","y":2021,"id":"2020/19-1434","sc":1,"by":{"0":"54, 56, 58, 59","2":"20, 25, 28"},"q":[{"src":"brief","b":2,"text":"better reflect[] the structure of supervision within the PTO and the nature of APJs’ duties.","cite":"141 S. Ct. at 1987"},{"src":"brief","b":2,"text":"[w]hat matters is that the [department head] have the discretion to review decisions.","cite":"141 S. Ct. at 1988"},{"src":"argument","who":"Mr. Fletcher","text":"We think that's the lesson from the plurality opinion in Arthrex. Also, in Free Enterprise Fund, this Court said the most telling problem with the scheme it confronted there was its novelty."}]},{"t":"case","label":"United States v. Batchelder","cite":"442 U.S. 114","y":1979,"id":"1978/78-776","sc":1,"by":{"0":"11, 35, 38, 39, 43","2":"16"},"q":[{"src":"brief","b":0,"text":"fulfilled its duty of controlling the mode of determining public rights cases asserted by the SEC.","cite":"442 U.S. 114"},{"src":"brief","b":0,"text":"different penalties for essentially the same conduct.","cite":"442 U.S. at 121"}]},{"t":"case","label":"United States v. Germaine","cite":"99 U.S. 508","y":1879,"id":"scdb/1878-198","sc":1,"by":{"0":"48"},"q":[{"src":"brief","b":0,"text":"nine-tenths of the persons rendering service to the government","cite":"99 U.S. 508, 509"}]},{"t":"case","label":"United States v. Gordon","cite":"548 F.2d 743","y":1977,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.2d/548/743/","by":{"0":"44"}},{"t":"case","label":"United States v. Grimaud","cite":"220 U.S. 506","y":1911,"id":"scdb/1910-122","sc":1,"by":{"0":"37","2":"17"},"q":[{"src":"brief","b":0,"text":"by the establishment of administrative rules and regulations.","cite":"220 U.S. 506, 517"},{"src":"brief","b":2,"text":"conferring upon executive officers power to make rules and regulations","cite":"220 U.S. 506, 517"}]},{"t":"case","label":"United States v. LaSalle Nat’l Bank","cite":"437 U.S. 298","y":1978,"id":"1977/77-365","sc":1,"by":{"0":"43"}},{"t":"case","label":"United States v. Perkins","cite":"116 U.S. 483","y":1886,"id":"scdb/1885-120","sc":1,"by":{"0":"34, 51","1":"56, 58","2":"18"},"q":[{"src":"brief","b":0,"text":"it may limit and restrict the power of removal as it deems best for the public interest.","cite":"116 U.S. 483, 485"},{"src":"brief","b":0,"text":"may limit and restrict the power of removal as it deems best for the public interest.","cite":"116 U.S. 483, 485"}]},{"t":"case","label":"Universal Camera Corp. v. NLRB","cite":"340 U.S. 474","y":1951,"id":"scdb/1950-038","sc":1,"by":{"0":"5, 58"}},{"t":"case","label":"Whitman v. American Trucking Ass’ns","cite":"531 U.S. 457","y":2001,"id":"2000/99-1257","sc":1,"by":{"0":"34, 36, 37"},"q":[{"src":"brief","b":0,"text":"unlawful[ly] delegati[ng] * * * legislative power.","cite":"531 U.S. 457, 472"},{"src":"brief","b":0,"text":"the degree of agency discretion that is acceptable varies according to the scope of the power congressionally conferred.","cite":"531 U.S. at 475"}]},{"t":"case","label":"Wiener v. United States","cite":"357 U.S. 349","y":1958,"id":"1957/52","sc":1,"by":{"0":"62"}},{"t":"case","label":"Withrow v. Larkin","cite":"421 U.S. 35","y":1975,"id":"1974/73-1573","sc":1,"by":{"0":"53"}},{"t":"case","label":"Wong Yang Sung v. McGrath","cite":"339 U.S. 33","y":1950,"id":"scdb/1949-048","sc":1,"by":{"0":"53, 66"},"q":[{"src":"brief","b":0,"text":"Pressures and influences properly enough directed toward officers responsible for formulating and administering policy constitute an unwholesome atmosphere in which to adjudicate","cite":"339 U.S. 33, 42"}]},{"t":"case","label":"Yakus v. United States","cite":"321 U.S. 414","y":1944,"id":"1940-1955/321us414","sc":1,"by":{"0":"37"}},{"t":"const","label":"Article II","clauses":[["executive-vesting","Executive Vesting Clause"],["natural-born","Natural-Born Citizen Clause"],["commander-in-chief","Commander in Chief Clause"],["pardon","Pardon Clause"],["treaty","Treaty Clause"],["appointments","Appointments Clause"],["take-care","Take Care Clause"],["impeachment","Impeachment"]],"by":{"0":"8, 10, 12, 16, 34, 45, 47-50, 55-57, 65"}},{"t":"usc","label":"5 U.S.C. § 551","url":"https://www.law.cornell.edu/uscode/text/5/551","stext":{"head":"§551. Definitions","paras":[[0,"For the purpose of this subchapter—"],[1,"(1) \"agency\" means each authority of the Government of the United States, whether or not it is within or subject to review by another agency, but does not include—"],[2,"(A) the Congress;"],[2,"(B) the courts of the United States;"],[2,"(C) the governments of the territories or possessions of the United States;"],[2,"(D) the government of the District of Columbia;"],[1,"or except as to the requirements of section 552 of this title—"],[2,"(E) agencies composed of representatives of the parties or of representatives of organizations of the parties to the disputes determined by them;"],[2,"(F) courts martial and military commissions;"],[2,"(G) military authority exercised in the field in time of war or in occupied territory; or"],[2,"(H) functions conferred by sections 1738, 1739, 1743, and 1744 of title 12; subchapter II of chapter 471 of title 49; or sections 1884, 1891–1902, and former section 1641(b)(2), of title 50, appendix; 1"],[1,"(2) \"person\" includes an individual, partnership, corporation, association, or public or private organization other than an agency;"],[1,"(3) \"party\" includes a person or agency named or admitted as a party, or properly seeking and entitled as of right to be admitted as a party, in an agency proceeding, and a person or agency admitted by an agency as a party for limited purposes;"],[1,"(4) \"rule\" means the whole or a part of an agency statement of general or particular applicability and future effect designed to implement, interpret, or prescribe law or policy or describing the organization, procedure, or practice requirements of an agency and includes the approval or prescription for the future of rates, wages, corporate or financial structures or reorganizations thereof, prices, facilities, appliances, services or allowances therefor or of valuations, costs, or accounting, or practices bearing on any of the foregoing;"],[1,"(5) \"rule making\" means agency process for formulating, amending, or repealing a rule;"],[1,"(6) \"order\" means the whole or a part of a final disposition, whether affirmative, negative, injunctive, or declaratory in form, of an agency in a matter other than rule making but including licensing;"],[1,"(7) \"adjudication\" means agency process for the formulation of an order;"],[1,"(8) \"license\" includes the whole or a part of an agency permit, certificate, approval, registration, charter, membership, statutory exemption or other form of permission;"],[1,"(9) \"licensing\" includes agency process respecting the grant, renewal, denial, revocation, suspension, annulment, withdrawal, limitation, amendment, modification, or conditioning of a license;"],[1,"(10) \"sanction\" includes the whole or a part of an agency—"],[2,"(A) prohibition, requirement, limitation, or other condition affecting the freedom of a person;"],[2,"(B) withholding of relief;"],[2,"(C) imposition of penalty or fine;"],[2,"(D) destruction, taking, seizure, or withholding of property;"],[2,"(E) assessment of damages, reimbursement, restitution, compensation, costs, charges, or fees;"],[2,"(F) requirement, revocation, or suspension of a license; or"],[2,"(G) taking other compulsory or restrictive action;"],[1,"(11) \"relief\" includes the whole or a part of an agency—"],[2,"(A) grant of money, assistance, license, authority, exemption, exception, privilege, or remedy;"],[2,"(B) recognition of a claim, right, immunity, privilege, exemption, or exception; or"],[2,"(C) taking of other action on the application or petition of, and beneficial to, a person;"],[1,"(12) \"agency proceeding\" means an agency process as defined by paragraphs (5), (7), and (9) of this section;"],[1,"(13) \"agency action\" includes the whole or a part of an agency rule, order, license, sanction, relief, or the equivalent or denial thereof, or failure to act; and"],[1,"(14) \"ex parte communication\" means an oral or written communication not on the public record with respect to which reasonable prior notice to all parties is not given, but it shall not include requests for status reports on any matter or proceeding covered by this subchapter."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/5/551?type=usc&year=mostrecent&link-type=html"},"by":{"0":"4","2":"3"}},{"t":"usc","label":"5 U.S.C. § 554","url":"https://www.law.cornell.edu/uscode/text/5/554","by":{"0":"4"}},{"t":"usc","label":"5 U.S.C. § 556","url":"https://www.law.cornell.edu/uscode/text/5/556","subs":["(a)","(b)","(c)"],"by":{"0":"57, 5, 5, 57"},"q":[{"src":"brief","b":0,"text":"[s]ubject to published rules of the agency.","cite":"5 U.S.C. 556(c)"}]},{"t":"usc","label":"5 U.S.C. § 557","url":"https://www.law.cornell.edu/uscode/text/5/557","subs":["(b)"],"by":{"0":"5, 45, 58"}},{"t":"usc","label":"5 U.S.C. § 701","url":"https://www.law.cornell.edu/uscode/text/5/701","subs":["(a)(2)"],"by":{"0":"35"},"q":[{"src":"brief","b":0,"text":"committed to agency discretion by law","cite":"5 U.S.C. 701(a)(2)"}]},{"t":"usc","label":"33 U.S.C. § 1251","url":"https://www.law.cornell.edu/uscode/text/33/1251","by":{"0":"28"}},{"t":"law","label":"Pub. L. No. 98-376","url":"https://www.govinfo.gov/link/statute/98/1264","by":{"0":"4"}},{"t":"usc","label":"15 U.S.C. § 80b-1","url":"https://www.law.cornell.edu/uscode/text/15/80b-1","by":{"0":"2, 24","1":"3"}},{"t":"usc","label":"15 U.S.C. § 80b-3","url":"https://www.law.cornell.edu/uscode/text/15/80b-3","by":{"0":"30"}},{"t":"usc","label":"15 U.S.C. § 80b-6","url":"https://www.law.cornell.edu/uscode/text/15/80b-6","subs":["(4)"],"by":{"0":"30","1":"4, 36"}},{"t":"usc","label":"15 U.S.C. § 80b-9","url":"https://www.law.cornell.edu/uscode/text/15/80b-9","by":{"0":"2"}},{"t":"usc","label":"15 U.S.C. § 80a-1","url":"https://www.law.cornell.edu/uscode/text/15/80a-1","by":{"0":"2"}},{"t":"usc","label":"29 U.S.C. § 651","url":"https://www.law.cornell.edu/uscode/text/29/651","stext":{"head":"§651. Congressional statement of findings and declaration of purpose and policy","paras":[[0,"(a) The Congress finds that personal injuries and illnesses arising out of work situations impose a substantial burden upon, and are a hindrance to, interstate commerce in terms of lost production, wage loss, medical expenses, and disability compensation payments."],[0,"(b) The Congress declares it to be its purpose and policy, through the exercise of its powers to regulate commerce among the several States and with foreign nations and to provide for the general welfare, to assure so far as possible every working man and woman in the Nation safe and healthful working conditions and to preserve our human resources—"],[1,"(1) by encouraging employers and employees in their efforts to reduce the number of occupational safety and health hazards at their places of employment, and to stimulate employers and employees to institute new and to perfect existing programs for providing safe and healthful working conditions;"],[1,"(2) by providing that employers and employees have separate but dependent responsibilities and rights with respect to achieving safe and healthful working conditions;"],[1,"(3) by authorizing the Secretary of Labor to set mandatory occupational safety and health standards applicable to businesses affecting interstate commerce, and by creating an Occupational Safety and Health Review Commission for carrying out adjudicatory functions under this chapter;"],[1,"(4) by building upon advances already made through employer and employee initiative for providing safe and healthful working conditions;"],[1,"(5) by providing for research in the field of occupational safety and health, including the psychological factors involved, and by developing innovative methods, techniques, and approaches for dealing with occupational safety and health problems;"],[1,"(6) by exploring ways to discover latent diseases, establishing causal connections between diseases and work in environmental conditions, and conducting other research relating to health problems, in recognition of the fact that occupational health standards present problems often different from those involved in occupational safety;"],[1,"(7) by providing medical criteria which will assure insofar as practicable that no employee will suffer diminished health, functional capacity, or life expectancy as a result of his work experience;"],[1,"(8) by providing for training programs to increase the number and competence of personnel engaged in the field of occupational safety and health;"],[1,"(9) by providing for the development and promulgation of occupational safety and health standards;"],[1,"(10) by providing an effective enforcement program which shall include a prohibition against giving advance notice of any inspection and sanctions for any individual violating this prohibition;"],[1,"(11) by encouraging the States to assume the fullest responsibility for the administration and enforcement of their occupational safety and health laws by providing grants to the States to assist in identifying their needs and responsibilities in the area of occupational safety and health, to develop plans in accordance with the provisions of this chapter, to improve the administration and enforcement of State occupational safety and health laws, and to conduct experimental and demonstration projects in connection therewith;"],[1,"(12) by providing for appropriate reporting procedures with respect to occupational safety and health which procedures will help achieve the objectives of this chapter and accurately describe the nature of the occupational safety and health problem;"],[1,"(13) by encouraging joint labor-management efforts to reduce injuries and disease arising out of employment."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/29/651?type=usc&year=mostrecent&link-type=html"},"by":{"0":"21","2":"8"},"q":[{"src":"opinion","who":"Opinion of the Court (Chief Justice Roberts)","text":"develop[ ] innovative methods, techniques, and approaches for dealing with occu- Page Proof Pending Publication pational safety and health problems.","cite":"29 U. S. C. § 651(b)(5)"}]},{"t":"usc","label":"15 U.S.C. § 77a","url":"https://www.law.cornell.edu/uscode/text/15/77a","stext":{"head":"§77a. Short title","paras":[[0,"This subchapter may be cited as the \"Securities Act of 1933\"."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/15/77a?type=usc&year=mostrecent&link-type=html"},"by":{"0":"2","1":"36, 3"},"q":[{"src":"brief","b":1,"text":"to engage in any transaction, practice, or course of business which operates or would operate as a fraud or deceit upon the purchaser.","cite":"15 U.S.C. §§ 77a"}]},{"t":"usc","label":"15 U.S.C. § 77h-1","url":"https://www.law.cornell.edu/uscode/text/15/77h-1","subs":["(g)"],"by":{"0":"30","2":"9, 9"}},{"t":"usc","label":"15 U.S.C. § 77q","url":"https://www.law.cornell.edu/uscode/text/15/77q","subs":["(a)","(a)(2)"],"by":{"0":"30","1":"4"}},{"t":"usc","label":"15 U.S.C. § 77t","url":"https://www.law.cornell.edu/uscode/text/15/77t","by":{"0":"4"}},{"t":"usc","label":"15 U.S.C. § 78a","url":"https://www.law.cornell.edu/uscode/text/15/78a","by":{"0":"2","1":"3"}},{"t":"usc","label":"15 U.S.C. § 78b","url":"https://www.law.cornell.edu/uscode/text/15/78b","by":{"0":"3, 24, 30"},"q":[{"src":"brief","b":0,"text":"are effected with a national public interest which makes it necessary to provide for regulation and control of such transactions and of practices and matters related thereto.","cite":"15 U.S.C. 78b"},{"src":"brief","b":0,"text":"provid[ing] for regulation and control of [securities] transactions.","cite":"15 U.S.C. 78b"}]},{"t":"usc","label":"15 U.S.C. § 78d","url":"https://www.law.cornell.edu/uscode/text/15/78d","subs":["(a)"],"by":{"0":"2"}},{"t":"usc","label":"15 U.S.C. § 78d-1","url":"https://www.law.cornell.edu/uscode/text/15/78d-1","subs":["(a)"],"by":{"0":"4"}},{"t":"usc","label":"15 U.S.C. § 78j","url":"https://www.law.cornell.edu/uscode/text/15/78j","subs":["(1946)","(1958)","(b)"],"by":{"0":"30, 30","1":"4, 36"}},{"t":"usc","label":"15 U.S.C. § 78u","url":"https://www.law.cornell.edu/uscode/text/15/78u","subs":["(d)"],"by":{"0":"3, 24"}},{"t":"usc","label":"15 U.S.C. § 78u-2","url":"https://www.law.cornell.edu/uscode/text/15/78u-2","by":{"0":"3, 24","2":"9"}},{"t":"usc","label":"15 U.S.C. § 78u-3","url":"https://www.law.cornell.edu/uscode/text/15/78u-3","by":{"0":"3, 24","2":"9"}},{"t":"usc","label":"15 U.S.C. § 78y","url":"https://www.law.cornell.edu/uscode/text/15/78y","subs":["(a)(1)"],"by":{"0":"3","1":"7, 11, 69-72"}},{"t":"usc","label":"5 U.S.C. § 1201","url":"https://www.law.cornell.edu/uscode/text/5/1201","by":{"0":"5"}},{"t":"usc","label":"5 U.S.C. § 1202","url":"https://www.law.cornell.edu/uscode/text/5/1202","subs":["(d)"],"stext":{"head":"§1202. Term of office; filling vacancies; removal","paras":[[0,"(a) The term of office of each member of the Merit Systems Protection Board is 7 years."],[0,"(b) A member appointed to fill a vacancy occurring before the end of a term of office of the member's predecessor serves for the remainder of that term. Any appointment to fill a vacancy is subject to the requirements of section 1201. Any new member serving only a portion of a seven-year term in office may continue to serve until a successor is appointed and has qualified, except that such member may not continue to serve for more than one year after the date on which the term of the member would otherwise expire, unless reappointed."],[0,"(c) Any member appointed for a 7-year term may not be reappointed to any following term but may continue to serve beyond the expiration of the term until a successor is appointed and has qualified, except that such member may not continue to serve for more than one year after the date on which the term of the member would otherwise expire under this section."],[0,"(d) Any member may be removed by the President only for inefficiency, neglect of duty, or malfeasance in office."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/5/1202?type=usc&year=mostrecent&link-type=html"},"by":{"0":"5, 10, 61","2":"21"},"q":[{"src":"brief","b":0,"text":"only for inefficiency, neglect of duty, or malfeasance in office,","cite":"5 U.S.C. 1202(d)"},{"src":"brief","b":0,"text":"MSPB members ‘may be removed by the President only for inefficiency, neglect of duty, or malfeasance in office,’","cite":"5 U.S.C. 1202(d)"},{"src":"brief","b":2,"text":"inefficiency, neglect of duty, or malfeasance in office,","cite":"5 U.S.C. 1202(d)"}]},{"t":"usc","label":"5 U.S.C. § 1215","url":"https://www.law.cornell.edu/uscode/text/5/1215","by":{"0":"6"}},{"t":"usc","label":"5 U.S.C. § 3105","url":"https://www.law.cornell.edu/uscode/text/5/3105","by":{"0":"4, 5","2":"21"}},{"t":"usc","label":"5 U.S.C. § 3502","url":"https://www.law.cornell.edu/uscode/text/5/3502","by":{"0":"6"}},{"t":"usc","label":"5 U.S.C. § 7104","url":"https://www.law.cornell.edu/uscode/text/5/7104","subs":["(b)"],"by":{"0":"64"}},{"t":"usc","label":"5 U.S.C. § 7521","url":"https://www.law.cornell.edu/uscode/text/5/7521","subs":["(a)","(b)(A)","(b)(B)","(b)(C)"],"stext":{"head":"§7521. Actions against administrative law judges","paras":[[0,"(a) An action may be taken against an administrative law judge appointed under section 3105 of this title by the agency in which the administrative law judge is employed only for good cause established and determined by the Merit Systems Protection Board on the record after opportunity for hearing before the Board."],[0,"(b) The actions covered by this section are—"],[1,"(1) a removal;"],[1,"(2) a suspension;"],[1,"(3) a reduction in grade;"],[1,"(4) a reduction in pay; and"],[1,"(5) a furlough of 30 days or less;"],[0,"but do not include—"],[1,"(A) a suspension or removal under section 7532 of this title;"],[1,"(B) a reduction-in-force action under section 3502 of this title; or"],[1,"(C) any action initiated under section 1215 of this title."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/5/7521?type=usc&year=mostrecent&link-type=html"},"by":{"0":"6, 6, 6, 6, 6","1":"63","2":"18, 21, 22, 24-26, 29, 17, 21, 27, 28"},"q":[{"src":"brief","b":0,"text":"on the record after opportunity for hearing.","cite":"5 U.S.C. 7521"},{"src":"brief","b":0,"text":"only for good cause established and determined by the Merit Systems Protection Board on the record after opportunity for hearing before the Board.","cite":"5 U.S.C. 7521(a)"},{"src":"brief","b":2,"text":"only for good cause established and determined by the [MSPB].","cite":"5 U.S.C. 7521(a)"}]},{"t":"usc","label":"5 U.S.C. § 7532","url":"https://www.law.cornell.edu/uscode/text/5/7532","subs":["(b)"],"by":{"0":"6"},"q":[{"src":"brief","b":0,"text":"he determines that removal is necessary or advisable in the interests of national security.","cite":"5 U.S.C. 7532(b)"}]},{"t":"usc","label":"5 U.S.C. § 7703","url":"https://www.law.cornell.edu/uscode/text/5/7703","by":{"0":"6"}},{"t":"usc","label":"7 U.S.C. § 9","url":"https://www.law.cornell.edu/uscode/text/7/9","subs":["(4)","(10)"],"by":{"0":"33, 33"}},{"t":"usc","label":"7 U.S.C. § 13a-1","url":"https://www.law.cornell.edu/uscode/text/7/13a-1","subs":["(a)","(d)"],"by":{"0":"33, 33"}},{"t":"usc","label":"7 U.S.C. § 6992","url":"https://www.law.cornell.edu/uscode/text/7/6992","subs":["(b)(2)"],"by":{"0":"55"}},{"t":"usc","label":"10 U.S.C. § 942","url":"https://www.law.cornell.edu/uscode/text/10/942","subs":["(c)"],"by":{"0":"55, 64"}},{"t":"usc","label":"12 U.S.C. § 5563","url":"https://www.law.cornell.edu/uscode/text/12/5563","subs":["(a)"],"by":{"0":"33"}},{"t":"usc","label":"12 U.S.C. § 5564","url":"https://www.law.cornell.edu/uscode/text/12/5564","subs":["(a)"],"by":{"0":"33"}},{"t":"usc","label":"12 U.S.C. § 5565","url":"https://www.law.cornell.edu/uscode/text/12/5565","subs":["(a)(1)","(a)(2)(H)"],"by":{"0":"33, 33"}},{"t":"usc","label":"16 U.S.C. § 1852","url":"https://www.law.cornell.edu/uscode/text/16/1852","subs":["(b)(6)(B)"],"by":{"0":"64"}},{"t":"usc","label":"21 U.S.C. § 335b","url":"https://www.law.cornell.edu/uscode/text/21/335b","subs":["(b)(1)"],"by":{"0":"33"}},{"t":"usc","label":"22 U.S.C. § 4106","url":"https://www.law.cornell.edu/uscode/text/22/4106","subs":["(e)"],"by":{"0":"64"}},{"t":"usc","label":"22 U.S.C. § 4135","url":"https://www.law.cornell.edu/uscode/text/22/4135","subs":["(d)"],"by":{"0":"64"}},{"t":"usc","label":"26 U.S.C. § 7443","url":"https://www.law.cornell.edu/uscode/text/26/7443","by":{"0":"64"}},{"t":"usc","label":"28 U.S.C. § 152","url":"https://www.law.cornell.edu/uscode/text/28/152","subs":["(e)"],"by":{"0":"54, 64"}},{"t":"usc","label":"28 U.S.C. § 157","url":"https://www.law.cornell.edu/uscode/text/28/157","subs":["(b)(2)(H)"],"by":{"0":"26"}},{"t":"usc","label":"28 U.S.C. § 176","url":"https://www.law.cornell.edu/uscode/text/28/176","subs":["(b)"],"by":{"0":"64"}},{"t":"usc","label":"28 U.S.C. § 631","url":"https://www.law.cornell.edu/uscode/text/28/631","subs":["(i)"],"by":{"0":"54, 64"}},{"t":"usc","label":"29 U.S.C. § 153","url":"https://www.law.cornell.edu/uscode/text/29/153","subs":["(a)"],"by":{"0":"64"}},{"t":"usc","label":"33 U.S.C. § 1319","url":"https://www.law.cornell.edu/uscode/text/33/1319","subs":["(a)","(b)","(g)"],"by":{"0":"33, 33, 33"}},{"t":"usc","label":"35 U.S.C. § 282","url":"https://www.law.cornell.edu/uscode/text/35/282","subs":["(b)(2)","(b)(3)"],"by":{"0":"33, 33"}},{"t":"usc","label":"38 U.S.C. § 7101","url":"https://www.law.cornell.edu/uscode/text/38/7101","subs":["(b)(2)"],"by":{"0":"55, 64"}},{"t":"usc","label":"38 U.S.C. § 7253","url":"https://www.law.cornell.edu/uscode/text/38/7253","by":{"0":"55, 64"}},{"t":"usc","label":"39 U.S.C. § 3018","url":"https://www.law.cornell.edu/uscode/text/39/3018","subs":["(c)","(d)","(g)"],"by":{"0":"33, 33, 33"}},{"t":"usc","label":"41 U.S.C. § 7105","url":"https://www.law.cornell.edu/uscode/text/41/7105","subs":["(b)(3)"],"by":{"0":"55"}},{"t":"usc","label":"48 U.S.C. § 1424b","url":"https://www.law.cornell.edu/uscode/text/48/1424b","subs":["(a)"],"by":{"0":"54"}},{"t":"usc","label":"48 U.S.C. § 1614","url":"https://www.law.cornell.edu/uscode/text/48/1614","subs":["(a)"],"by":{"0":"54"}},{"t":"usc","label":"48 U.S.C. § 1821","url":"https://www.law.cornell.edu/uscode/text/48/1821","subs":["(b)(1)"],"by":{"0":"54"}},{"t":"rule","label":"Fed. R. Crim. P. 7","url":"https://www.law.cornell.edu/rules/frcrmp/rule_7","subs":["(a)"],"by":{"0":"44"}},{"t":"case","label":"Aaron v. SEC","cite":"446 U.S. 680","y":1980,"id":"1979/79-66","sc":1,"by":{"1":"36"}},{"t":"case","label":"Advoc. Health Care Network v. Stapleton","cite":"581 U.S. 468","y":2017,"url":"https://supreme.justia.com/cases/federal/us/581/468/","sc":1,"by":{"1":"72"}},{"t":"case","label":"Alaska Airlines v. Brock","cite":"480 U.S. 678","y":1987,"id":"1986/85-920","sc":1,"by":{"1":"67"},"q":[{"src":"brief","b":1,"text":"inquiry in evaluating severability is whether the statute will function in a manner consistent with the intent of Congress","cite":"480 U.S. 678, 685"}]},{"t":"case","label":"Arizona v. Fulminante","cite":"499 U.S. 279","y":1991,"id":"1990/89-839","sc":1,"by":{"1":"66"}},{"t":"case","label":"Axon Enterprise, Inc., v. F.T.C.","cite":"143 S. Ct. 890","y":2023,"url":"https://www.courtlistener.com/c/S.%20Ct./143/890/","sc":1,"by":{"1":"4"},"q":[{"src":"argument","who":"Mr. Fletcher","text":"Justice Thomas, you have addressed this at length in Axon and in other writings. You know, we -- the place where I think we would depart from you is we think that the Court's cases going back all the way to Murray's Lessee stand for the proposition that it can be a matter of public rights within -- for purposes of Article III even if private property was involved."}]},{"t":"case","label":"Barnhart v. Sigmon Coal Co.","cite":"534 U.S. 438","y":2002,"id":"2001/00-1307","sc":1,"by":{"1":"72"}},{"t":"case","label":"Bowsher v. Synar","cite":"478 U.S. 714","y":1986,"id":"1985/85-1377","sc":1,"by":{"1":"42, 54-55, 68-69"}},{"t":"case","label":"Curtis v. Loether","cite":"415 U.S. 189","y":1974,"id":"1973/72-1035","sc":1,"by":{"1":"26"},"q":[{"src":"brief","b":1,"text":"the right to trial by jury as it existed [in England] in 1791.","cite":"415 U.S. 189, 193"}]},{"t":"case","label":"Dimick v. Schiedt","cite":"293 U.S. 474","y":1935,"id":"scdb/1934-155","sc":1,"by":{"1":"12-13"}},{"t":"case","label":"Dura Pharm., Inc. v. Broudo","cite":"544 U.S. 336","y":2005,"id":"2004/03-932","sc":1,"by":{"1":"36"}},{"t":"case","label":"Freytag v. Commissioner","cite":"501 U.S. 868","y":1991,"id":"1990/90-762","sc":1,"by":{"1":"65"},"q":[{"src":"brief","b":1,"text":"preserves another aspect of the Constitution's structural integrity by preventing the diffusion of the appointment power.","cite":"501 U.S. 868, 878"}]},{"t":"case","label":"Garland v. Ming Dai","cite":"141 S. Ct. 1669","y":2021,"id":"2020/19-1155","sc":1,"by":{"1":"70"}},{"t":"case","label":"Independent Brokers-Dealers Trade Ass’n v. SEC","cite":"442 F.2d 132","y":1971,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/442/132/","by":{"1":"71"}},{"t":"case","label":"J.W. Hampton, Jr., & Co. v. United States","cite":"276 U.S. 394","y":1928,"id":"1900-1940/276us394","sc":1,"by":{"1":"48"}},{"t":"case","label":"Kixmiller v. SEC","cite":"492 F.2d 641","y":1974,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/492/641/","by":{"1":"71"}},{"t":"case","label":"Markman v. Westview Instruments, Inc.","cite":"517 U.S. 370","y":1996,"id":"1995/95-26","sc":1,"by":{"1":"12-13"}},{"t":"case","label":"Murphy v. Nat'l Collegiate Athletic Ass'n","cite":"138 S. Ct. 1461","y":2018,"id":"2017/16-476","sc":1,"by":{"1":"68"},"q":[{"src":"brief","b":1,"text":"cannot rewrite a statute and give it an effect altogether different from that sought by the measure viewed as a whole.","cite":"138 S. Ct. 1461, 1482"}]},{"t":"case","label":"New Hampshire v. Maine","cite":"532 U.S. 742","y":2001,"id":"2000/130_orig","sc":1,"by":{"1":"54"},"q":[{"src":"brief","b":1,"text":"and then relying on a contradictory argument to prevail in another phase,","cite":"532 U.S. 742, 749"}]},{"t":"case","label":"NLRB v. Bell Aerospace Co.","cite":"416 U.S. 267","y":1974,"id":"1973/72-1598","sc":1,"by":{"1":"59"},"q":[{"src":"brief","b":1,"text":"promulgate[] new standard[s] that w[ill] govern future conduct.","cite":"416 U.S. 267, 292-94"}]},{"t":"case","label":"Northern Pipeline Constr. Co. v. Marathon Pipeline Co.","cite":"458 U.S. 50","y":1982,"id":"1981/81-150","sc":1,"by":{"1":"28, 31"},"q":[{"src":"brief","b":1,"text":"something is seriously amiss with our jurisprudence in this area.","cite":"458 U.S. 50, 111"},{"src":"opinion","who":"Opinion of the Court (Chief Justice Roberts)","text":"is made of `the stuff of the traditional actions at common law tried by the courts at Westminster in 1789.'","cite":"458 U. S. 50, 90"},{"src":"opinion","who":"Opinion of the Court (Chief Justice Roberts)","text":"[E]ven with respect to matters that arguably fall within the scope of the `public rights' doctrine, the presumption is in favor of Art. III courts.","cite":"458 U. S., at 69, n. 23"},{"src":"opinion","who":"Opinion of the Court (Chief Justice Roberts)","text":"the presence of the United States as a proper party to the proceeding is . . . suffcient","cite":"458 U. S., at 69, n. 23"},{"src":"argument","who":"Mr. Fletcher","text":"So the plurality in Northern Pipeline, which I think, you know, also recognized exactly this issue, sort of acknowledged that concern and said the reason is that the Article III question is grounded in the separation of powers."},{"src":"argument","who":"Justice Kavanaugh","text":"And in Stern, the Chief Justice's opinion said that public rights extended, quoting Northern Pipeline's plurality, only to matters arising between individuals and the government in connection with the performance of the constitutional functions of the executive or legislative departments that historically could have been determined exclusively by those branches, which suggests a line that may track the Due Process Clause between benefits and penalties."},{"src":"argument","who":"Justice Kagan","text":"What have been thought the hard cases -- Northern Pipeline, Schor, Granfinanciera, Stern, Oil States -- these are all private people on both sides of the V, and, nonetheless, we've held that public rights might be involved because their disputes are embedded in federal statutory schemes."}]},{"t":"case","label":"Railroad Retirement Bd. v. Alton R. Co.","cite":"295 U.S. 330","y":1935,"id":"scdb/1934-051","sc":1,"by":{"1":"68"}},{"t":"case","label":"Republic of Sudan v. Harrison","cite":"139 S. Ct. 1048","y":2019,"id":"2018/16-1094","sc":1,"by":{"1":"72"},"q":[{"src":"brief","b":1,"text":"Congress generally acts intentionally when it uses particular language in one section of a statute but omits it in another.","cite":"139 S. Ct. 1048, 1058"}]},{"t":"case","label":"Ryder v. United States","cite":"515 U.S. 177","y":1995,"id":"1994/94-431","sc":1,"by":{"1":"65-67"}},{"t":"case","label":"SEC v. Chenery Corp.","cite":"318 U.S. 80","y":1943,"id":"scdb/1942-113","sc":1,"by":{"1":"70"}},{"t":"case","label":"(xi) Social Sec. Admin. v. Brennan","cite":"27 M.S.P.R. 242","y":1985,"url":"https://www.courtlistener.com/c/M.S.P.R./27/242/","by":{"1":"63"}},{"t":"case","label":"Social Sec. Admin. v. Glover","cite":"23 M.S.P.R. 57","y":1984,"url":"https://www.courtlistener.com/c/M.S.P.R./23/57/","by":{"1":"63"}},{"t":"case","label":"Steadman v. SEC","cite":"450 U.S. 91","y":1981,"id":"1980/79-1266","sc":1,"by":{"1":"71"},"q":[{"src":"brief","b":1,"text":"is the special statutory review proceeding relevant to the subject matter in a court specified by statute","cite":"450 U.S. 91, 105"}]},{"t":"case","label":"Thomas v. Union Carbide Agric. Prods. Co.","cite":"473 U.S. 568","y":1985,"id":"1984/84-497","sc":1,"by":{"1":"31, 38-39","2":"7, 8"},"q":[{"src":"opinion","who":"Opinion of the Court (Chief Justice Roberts)","text":"area of frequently arcane distinctions and confusing precedents.","cite":"473 U. S. 568, 583"},{"src":"opinion","who":"Justice Sotomayor, dissenting","text":"closely integrated into a public regulatory scheme","cite":"473 U. S. 568, 594"}]},{"t":"case","label":"United States v. Bitty","cite":"208 U.S. 393","y":1908,"id":"scdb/1907-081","sc":1,"by":{"1":"29"}},{"t":"case","label":"United States v. Wonson","cite":"28 F. Cas. 745","y":1812,"court":"C.C.D. Mass.","url":"https://www.courtlistener.com/c/F.%20Cas./28/745/","by":{"1":"12"}},{"t":"case","label":"(xii) Weaver v. Massachusetts","cite":"582 U.S. 286","y":2017,"url":"https://supreme.justia.com/cases/federal/us/582/286/","sc":1,"by":{"1":"66"},"q":[{"src":"brief","b":1,"text":"simply an error in the trial process itself.","cite":"582 U.S. 286, 295"},{"src":"brief","b":1,"text":"the effects of the error are simply too hard to measure.","cite":"582 U.S. at 295"}]},{"t":"case","label":"Whitman v. Am. Trucking Ass’ns","cite":"531 U.S. 437","y":2001,"url":"https://supreme.justia.com/cases/federal/us/531/437/","sc":1,"by":{"1":"49"}},{"t":"case","label":"Whitney Nat’l Bank in Jefferson Parish v. Bank of New Orleans & Trust Co.","cite":"85 S. Ct. 551","y":1965,"id":"1964/26","sc":1,"by":{"1":"45-56"}},{"t":"case","label":"Williams v. Taylor","cite":"529 U.S. 362","y":2000,"id":"1999/98-8384","sc":1,"by":{"1":"72"},"q":[{"src":"brief","b":1,"text":"give effect, if possible, to every clause and word of a statute.","cite":"529 U.S. 362, 404"}]},{"t":"const","label":"Article I, Section 1","clauses":[["legislative-vesting","Legislative Vesting Clause"]],"text":"All legislative Powers herein granted shall be vested in a Congress of the United States, which shall consist of a Senate and House of Representatives.","by":{"1":"47"}},{"t":"const","label":"Article II, Section 3","clauses":[["take-care","Take Care Clause"]],"text":"He shall from time to time give to the Congress Information of the State of the Union, and recommend to their Consideration such Measures as he shall judge necessary and expedient; he may, on extraordinary Occasions, convene both Houses, or either of them, and in Case of Disagreement between them, with Respect to the Time of Adjournment, he may adjourn them to such Time as he shall think proper; he shall receive Ambassadors and other public Ministers; he shall take Care that the Laws be faithfully executed, and shall Commission all the Officers of the United States.","by":{"1":"10,52, 54"}},{"t":"const","label":"Amendment VII","clauses":[["seventh-amendment","Seventh Amendment (Civil Jury)"]],"text":"In Suits at common law, where the value in controversy shall exceed twenty dollars, the right of trial by jury shall be preserved, and no fact tried by a jury, shall be otherwise re-examined in any Court of the United States, than according to the rules of the common law.","by":{"1":"7-9, 12-13, 23, 25-46","2":"1, 3-6, 11-16, 29"}},{"t":"usc","label":"5 U.S.C. § 703","url":"https://www.law.cornell.edu/uscode/text/5/703","by":{"1":"71"}},{"t":"usc","label":"5 U.S.C. § 706","url":"https://www.law.cornell.edu/uscode/text/5/706","stext":{"head":"§706. Scope of review","paras":[[0,"To the extent necessary to decision and when presented, the reviewing court shall decide all relevant questions of law, interpret constitutional and statutory provisions, and determine the meaning or applicability of the terms of an agency action. The reviewing court shall—"],[1,"(1) compel agency action unlawfully withheld or unreasonably delayed; and"],[1,"(2) hold unlawful and set aside agency action, findings, and conclusions found to be—"],[2,"(A) arbitrary, capricious, an abuse of discretion, or otherwise not in accordance with law;"],[2,"(B) contrary to constitutional right, power, privilege, or immunity;"],[2,"(C) in excess of statutory jurisdiction, authority, or limitations, or short of statutory right;"],[2,"(D) without observance of procedure required by law;"],[2,"(E) unsupported by substantial evidence in a case subject to sections 556 and 557 of this title or otherwise reviewed on the record of an agency hearing provided by statute; or"],[2,"(F) unwarranted by the facts to the extent that the facts are subject to trial de novo by the reviewing court."],[0,"In making the foregoing determinations, the court shall review the whole record or those parts of it cited by a party, and due account shall be taken of the rule of prejudicial error."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/5/706?type=usc&year=mostrecent&link-type=html"},"by":{"1":"69-71","2":"30"}},{"t":"reg","label":"5 C.F.R. § 1201.140","url":"https://www.ecfr.gov/current/title-5/section-1201.140","subs":["(b)"],"by":{"1":"63"}},{"t":"usc","label":"15 U.S.C. § 77i","url":"https://www.law.cornell.edu/uscode/text/15/77i","by":{"1":"7, 69"}},{"t":"usc","label":"15 U.S.C. § 80b-13","url":"https://www.law.cornell.edu/uscode/text/15/80b-13","by":{"1":"7, 69"}},{"t":"reg","label":"17 C.F.R. § 240.10b-5","url":"https://www.ecfr.gov/current/title-17/section-240.10b-5","subs":["(b)"],"by":{"1":"4"}},{"t":"reg","label":"17 C.F.R. § 275.206","url":"https://www.ecfr.gov/current/title-17/section-275.206","subs":["(4)"],"by":{"1":"4"}},{"t":"usc","label":"28 U.S.C. § 1254","url":"https://www.law.cornell.edu/uscode/text/28/1254","subs":["(1)"],"by":{"1":"2"}},{"t":"usc","label":"28 U.S.C. § 2106","url":"https://www.law.cornell.edu/uscode/text/28/2106","by":{"1":"69-70"}},{"t":"law","label":"Dodd-Frank Wall Street Reform and Consumer Protection Act, Pub. L. No. 111-203","url":"https://www.govinfo.gov/link/plaw/111/public/203","by":{"1":"3, 8"}},{"t":"law","label":"Pub. L. No. 101-429","url":"https://www.govinfo.gov/link/statute/104/931","by":{"1":"3"}},{"t":"case","label":"Allen v. Cooper","cite":"140 S. Ct. 994","y":2020,"id":"2019/18-877","sc":1,"by":{"2":"5, 12"}},{"t":"case","label":"Barr v. American Ass’n of Political Consultants, Inc.","cite":"140 S. Ct. 2335","y":2020,"id":"2019/19-631","sc":1,"by":{"2":"28"},"q":[{"src":"brief","b":2,"text":"a game of gotcha against Congress, where litigants can ride a discrete constitutional flaw in a statute to take down the whole, otherwise constitutional statute.","cite":"140 S. Ct. 2335, 2351"}]},{"t":"case","label":"Free Enter. Fund v. PCAOB: 537 F.3d 667, (D.C. Cir. 2008), aff ’d in part rev’d in part and remanded","cite":"561 U.S. 447","y":2020,"url":"https://supreme.justia.com/cases/federal/us/561/447/","sc":1,"by":{"2":"23"},"q":[{"src":"brief","b":2,"text":"problematic portions while leaving the remainder intact.","cite":"561 U.S. at 508"},{"src":"opinion","who":"Justice Sotomayor, dissenting","text":"political power . . . operates.","cite":"561 U. S., at 523"}]},{"t":"case","label":"Haaland v. Brackeen","cite":"599 U.S. 255","y":2023,"id":"2022/21-376","sc":1,"by":{"2":"14"},"q":[{"src":"brief","b":2,"text":"theory for rationalizing this body of law.","cite":"599 U.S. 255, 279"}]},{"t":"case","label":"Herman & MacLean v. Huddleston","cite":"459 U.S. 375","y":1983,"id":"1982/81-680","sc":1,"by":{"2":"9"},"q":[{"src":"brief","b":2,"text":"the antifraud provisions of the securities laws are not coextensive with common law doctrines of fraud.","cite":"459 U.S. 375, 388389"}]},{"t":"case","label":"Little Sisters of the Poor Saints Peter & Paul Home v. Pennsylvania","cite":"140 S. Ct. 2367","y":2020,"id":"2019/19-431","sc":1,"by":{"2":"30"}},{"t":"case","label":"Northwest Airlines, Inc. v. County of Kent","cite":"510 U.S. 355","y":1994,"id":"1993/92-97","sc":1,"by":{"2":"30"}},{"t":"case","label":"Rapoport v. SEC","cite":"682 F.3d 98","y":2012,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/682/98/","by":{"2":"20"}},{"t":"const","label":"Article III","clauses":[["judicial-vesting","Judicial Vesting Clause"],["cases-controversies","Cases or Controversies (Justiciability)"],["original-jurisdiction","Original and Appellate Jurisdiction"],["treason","Treason Clause"]],"by":{"2":"1, 3-6, 8, 11, 13, 15, 16, 21"}},{"t":"usc","label":"29 U.S.C. § 654","url":"https://www.law.cornell.edu/uscode/text/29/654","by":{"2":"10"}},{"t":"usc","label":"5 U.S.C. § 7513","url":"https://www.law.cornell.edu/uscode/text/5/7513","subs":["(a)"],"by":{"2":"20"}},{"t":"usc","label":"28 U.S.C. § 594","url":"https://www.law.cornell.edu/uscode/text/28/594","subs":["(a)"],"by":{"2":"19"}}]};